"""Antigravity harness adapter acceptance tests — OFFICIAL hook contract.

The fixtures below follow the current official Antigravity hook payload
shapes (exa.hooks_pb protobuf JSON mapping, camelCase):

  common       : conversationId, workspacePaths, transcriptPath,
                 artifactDirectoryPath
  PreInvocation: preInvocationHookArgs{invocationNum, initialNumSteps}
  PostInvocation: postInvocationHookArgs{invocationNum, initialNumSteps}
  PostToolUse  : postToolHookArgs{stepIdx, toolCall{name,args}, error}
  Stop         : stopHookArgs{executionNum, terminationReason, error,
                 fullyIdle}

Result contracts asserted:

  PreInvocation with context -> {"injectSteps": [{"ephemeralMessage": ...}]}
  PreInvocation no injection  -> {}
  PostInvocation              -> {}
  PostToolUse                 -> {}
  Stop (any state)            -> {} (no stop/continue decision; ARCH-01)
  No Brain-internal debug fields ever leak into the hook response.

AutoInject visibility follows the canonical mode resolution
(SECOND_BRAIN_AUTOINJECT_* env > config/autoinject.toml > default shadow),
never a wrapper-local default. Lean influence comes only from the canonical
skill file through the harness-neutral lean_runtime helper.
"""

from __future__ import annotations

import io
import json
import os
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

from second_brain import cli, frontier, lean_runtime, semantic, skillforge, working_set

REPO_ROOT = Path(__file__).resolve().parent.parent
CANDIDATE_SKILL = REPO_ROOT / "skills" / "candidates" / "lean-code" / "SKILL.md"
WORKSPACE = Path(r"C:\work\p3-proj")


def _run_cli(
    home: Path,
    *args: str,
    stdin: str = "",
    env_extra: dict[str, str] | None = None,
) -> subprocess.CompletedProcess:
    env = dict(os.environ)
    for k in ("PYTHONHOME", "PYTHONPATH", "UV_INTERNAL__PYTHONHOME", "PYTHONSTARTUP"):
        env.pop(k, None)
    if env_extra:
        env.update(env_extra)
    return subprocess.run(
        [sys.executable, "-m", "second_brain", "--home", str(home), *args],
    """ARCH-01: an unresolved critical requirement must not make Brain force
    continuation, and Brain never answers stop/continue for the host."""
    session = f"agy-req-sess-{termination_reason or 'normal'}-{fully_idle}"
    working_set.add_requirement(
        brain, session, "All database queries must use prepared statements", importance="critical"
    )
    payload = {
        "conversationId": session,
        "workspacePaths": [str(WORKSPACE)],
        "modelName": "gemini-3.7-flash",
        "stopHookArgs": {
            "executionNum": 1,
            "terminationReason": termination_reason,
            "error": "",
            "fullyIdle": fully_idle,
        },
    }
    assert _hook(brain, payload) == {}


def test_stop_records_activation_with_unresolved_requirement(
    brain: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
) -> None:
    mid = semantic.list_memories(brain, scope="project")[0]["memory_id"]
    transcript = _transcript(tmp_path, "migration ordering rules")
    with transcript.open("a", encoding="utf-8") as fh:
        fh.write(
            json.dumps(
                {
                    "source": "MODEL",
                    "type": "PLANNER_RESPONSE",
                    "tool_calls": [{"name": "view_file", "args": {"command": f"echo {mid}"}}],
                }
            )
            + "\n"
        )
    conversation = "agy-feedback"

    def invoke(payload: dict) -> dict:
        monkeypatch.setattr(cli.sys, "stdin", io.StringIO(json.dumps(payload)))
        assert cli._cmd_antigravity_hook(brain) == 0
        return json.loads(capsys.readouterr().out)

    monkeypatch.setenv("SECOND_BRAIN_AUTOINJECT_MODE", "active")
    prepared = invoke(
        _pre_invocation_payload(conversation=conversation, transcript=str(transcript))
    )
    assert "injectSteps" in prepared
    working_set.add_requirement(
        brain, conversation, "verify nested tool activation", importance="critical"
    )
    stopped = invoke(
        {
            "conversationId": conversation,
            "workspacePaths": [str(WORKSPACE)],
            "transcriptPath": str(transcript),
            "stopHookArgs": {
                "executionNum": 1,
                "terminationReason": "",
                "error": "",
                "fullyIdle": True,
            },
        }
    )
    assert stopped == {}
    import sqlite3

    with sqlite3.connect(brain / "db" / "brain.sqlite") as conn:
        assert (
            conn.execute(
                "SELECT COUNT(*) FROM memory_activations WHERE memory_id = ? AND session_id = ?",
                (mid, conversation),
            ).fetchone()[0]
            == 1
        )
    return


